SELECT o.exchspot, md.quote_depth_snapshot->'metadata'->>'exchnote' AS exn, count(*)
FROM orders o JOIN marketdata md ON md.quote_depth_snapshot->'metadata'->>'mktcombo'=o.mktnote AND trim(md.quote_depth_snapshot->'metadata'->>'exchnote')=o.exchspot
GROUP BY 1,2 LIMIT 10;

SELECT o.recordvault, o.exchspot, o.mktnote, o.timecode, md.marketdatanode, md.quote_depth_snapshot->'metadata'->>'timetrack' AS tt
FROM orders o JOIN marketdata md ON md.quote_depth_snapshot->'metadata'->>'mktcombo'=o.mktnote AND trim(md.quote_depth_snapshot->'metadata'->>'exchnote')=o.exchspot
WHERE o.recordvault='OB148309';

